import React, { useState } from "react";
import { Calendar, Clipboard, BookOpen, User } from "lucide-react";

import ScheduleTab from "../tabs/ScheduleTab";
import ReportsTab from "../tabs/ReportsTab";
import TrainingTab from "../tabs/TrainingTab";

const Dashboard = () => {

  const [activeTab,setActiveTab] = useState("schedule");

  return (

    <div className="h-screen bg-[#FDFAD8] flex flex-col">

      {/* Header */}

      <header className="flex justify-between items-center p-8">

        <h1 className="text-4xl font-black italic text-[#47510B] uppercase">
          Worker Console
        </h1>

        <button className="flex items-center gap-2 bg-[#A1AED1] text-white px-4 py-2 rounded-xl">
          <User size={18}/>
          Worker
        </button>

      </header>


      {/* Main */}

      <div className="flex-1 flex items-center justify-center">

        {activeTab === "schedule" && <ScheduleTab/>}
        {activeTab === "reports" && <ReportsTab/>}
        {activeTab === "training" && <TrainingTab/>}

      </div>


      {/* Bottom Navigation */}

      <footer className="flex justify-center pb-10">

        <div className="bg-[#A1AED1] px-4 py-3 rounded-[40px] flex gap-6">

          <button onClick={()=>setActiveTab("schedule")} className="flex gap-2 items-center text-white font-bold">
            <Calendar size={20}/>
            Schedule
          </button>

          <button onClick={()=>setActiveTab("reports")} className="flex gap-2 items-center text-white font-bold">
            <Clipboard size={20}/>
            Reports
          </button>

          <button onClick={()=>setActiveTab("training")} className="flex gap-2 items-center text-white font-bold">
            <BookOpen size={20}/>
            Training
          </button>

        </div>

      </footer>

    </div>
  );
};

export default Dashboard;
